import{_ as e,o as l,c as a,a0 as o}from"./chunks/framework.Cp0xpwNH.js";const h=JSON.parse('{"title":"Quality Checklist","description":"","frontmatter":{},"headers":[],"relativePath":"QUALITY_CHECKLIST.md","filePath":"QUALITY_CHECKLIST.md"}'),t={name:"QUALITY_CHECKLIST.md"};function s(n,i,r,u,c,d){return l(),a("div",null,[...i[0]||(i[0]=[o('<h1 id="quality-checklist" tabindex="-1">Quality Checklist <a class="header-anchor" href="#quality-checklist" aria-label="Permalink to &quot;Quality Checklist&quot;">​</a></h1><p>Every lesson must pass this checklist before submission.</p><p>Use this to validate your work.</p><hr><h2 id="pre-submission-checklist" tabindex="-1">Pre-Submission Checklist <a class="header-anchor" href="#pre-submission-checklist" aria-label="Permalink to &quot;Pre-Submission Checklist&quot;">​</a></h2><h3 id="grammar-validation" tabindex="-1">Grammar Validation <a class="header-anchor" href="#grammar-validation" aria-label="Permalink to &quot;Grammar Validation&quot;">​</a></h3><ul><li><p>[ ] <strong>No unknown grammar introduced</strong></p><ul><li>Check <code>docs/GRAMMAR_MAP.md</code></li><li>All grammar in this lesson is either: <ul><li>Taught in this lesson, OR</li><li>Taught in a previous lesson, OR</li><li>Explicitly marked as review</li></ul></li></ul></li><li><p>[ ] <strong>All grammar concepts are explicit</strong></p><ul><li>No unexplained terminology</li><li>Every grammatical term is defined or referenced</li><li>Examples clarify concepts</li></ul></li><li><p>[ ] <strong>Grammar is referenced correctly</strong></p><ul><li>Links to <code>/shared/grammar/</code> files exist</li><li>References are accurate and current</li><li>No duplicated grammar explanations</li></ul></li></ul><h3 id="vocabulary-validation" tabindex="-1">Vocabulary Validation <a class="header-anchor" href="#vocabulary-validation" aria-label="Permalink to &quot;Vocabulary Validation&quot;">​</a></h3><ul><li><p>[ ] <strong>No unknown vocabulary introduced</strong></p><ul><li>Check <code>docs/VOCABULARY_ROADMAP.md</code></li><li>Check <code>shared/vocabulary/master.csv</code></li><li>All vocabulary is either: <ul><li>Taught in this lesson, OR</li><li>Taught in a previous lesson, OR</li><li>In the master vocabulary database</li></ul></li></ul></li><li><p>[ ] <strong>New vocabulary count is correct</strong></p><ul><li>Between 20-35 new vocabulary items (or as specified)</li><li>Vocabulary is essential for the level</li><li>No rare or irrelevant words</li></ul></li><li><p>[ ] <strong>All vocabulary exists in master database</strong></p><ul><li>Each word appears in <code>shared/vocabulary/master.csv</code></li><li>CSV entry includes all required fields</li><li>Pronunciation is provided</li><li>Example sentence is provided</li></ul></li><li><p>[ ] <strong>Vocabulary references are correct</strong></p><ul><li>Links to master database are accurate</li><li>CSV exports exist (or will be generated)</li><li>Tables match master database</li></ul></li></ul><h3 id="reading-validation" tabindex="-1">Reading Validation <a class="header-anchor" href="#reading-validation" aria-label="Permalink to &quot;Reading Validation&quot;">​</a></h3><ul><li><p>[ ] <strong>Reading uses only known grammar</strong></p><ul><li>No grammar concepts not yet taught</li><li>No complex structures without explanation</li><li>No future/past tense unless explicitly taught</li></ul></li><li><p>[ ] <strong>Reading uses only known vocabulary</strong></p><ul><li>Every word is from current or previous lessons</li><li>No unexplained words</li><li>No advanced vocabulary without context</li></ul></li><li><p>[ ] <strong>Reading is meaningful</strong></p><ul><li>Not just random sentences</li><li>Text tells a coherent story or conveys useful information</li><li>Practical and relevant to learner interests</li></ul></li></ul><h3 id="listening-validation" tabindex="-1">Listening Validation <a class="header-anchor" href="#listening-validation" aria-label="Permalink to &quot;Listening Validation&quot;">​</a></h3><ul><li>[ ] <strong>Listening uses only known grammar</strong></li><li>[ ] <strong>Listening uses only known vocabulary</strong></li><li>[ ] <strong>Listening is clear</strong><ul><li>Pronunciation is natural</li><li>Speech is at appropriate speed</li><li>Audio quality is good (if audio provided)</li></ul></li><li>[ ] <strong>Comprehension questions are provided</strong></li><li>[ ] <strong>Answer key is provided</strong></li></ul><h3 id="speaking-validation" tabindex="-1">Speaking Validation <a class="header-anchor" href="#speaking-validation" aria-label="Permalink to &quot;Speaking Validation&quot;">​</a></h3><ul><li>[ ] <strong>Speaking prompts are clear</strong><ul><li>Learner understands what&#39;s expected</li><li>Prompts use known vocabulary</li></ul></li><li>[ ] <strong>Model answers are provided</strong><ul><li>Natural and realistic</li><li>Use only known grammar and vocabulary</li><li>Appropriate length and complexity</li></ul></li></ul><h3 id="writing-validation" tabindex="-1">Writing Validation <a class="header-anchor" href="#writing-validation" aria-label="Permalink to &quot;Writing Validation&quot;">​</a></h3><ul><li><p>[ ] <strong>Writing exercises progress in difficulty</strong></p><ul><li>Start with structured (fill-in-blanks)</li><li>Move to semi-structured (sentence building)</li><li>End with open-ended (original writing)</li></ul></li><li><p>[ ] <strong>All writing exercises have examples or models</strong></p><ul><li>Sample answers provided</li><li>Model responses are clear</li></ul></li></ul><h3 id="lesson-structure-validation" tabindex="-1">Lesson Structure Validation <a class="header-anchor" href="#lesson-structure-validation" aria-label="Permalink to &quot;Lesson Structure Validation&quot;">​</a></h3><ul><li><p>[ ] <strong>All 20 sections are present</strong></p><ul><li>Lesson Header (1)</li><li>Lesson Goal (2)</li><li>Previous Knowledge (3)</li><li>Why This Matters (4)</li><li>Grammar (5)</li><li>Grammar Reasoning (6)</li><li>Vocabulary (7)</li><li>Pronunciation (8)</li><li>Dialogue (9)</li><li>Reading (10)</li><li>Listening (11)</li><li>Speaking (12)</li><li>Writing (13)</li><li>Common Mistakes (14)</li><li>Dutch Insight (15)</li><li>Memory Tricks (16)</li><li>Active Recall (17)</li><li>Quiz (18)</li><li>Homework (19)</li><li>Summary (20)</li></ul></li><li><p>[ ] <strong>No sections are empty</strong></p><ul><li>Even if not directly applicable, sections have content</li><li>Gaps are explained (e.g., &quot;Listening practice for this concept is in Review Lesson 2&quot;)</li></ul></li><li><p>[ ] <strong>All sections follow standards</strong></p><ul><li>Lesson section format matches <code>docs/LESSON_STANDARD.md</code></li><li>Grammar section format matches <code>docs/GRAMMAR_STANDARD.md</code></li><li>Vocabulary section format matches <code>docs/VOCABULARY_STANDARD.md</code></li></ul></li></ul><h3 id="content-quality-validation" tabindex="-1">Content Quality Validation <a class="header-anchor" href="#content-quality-validation" aria-label="Permalink to &quot;Content Quality Validation&quot;">​</a></h3><ul><li><p>[ ] <strong>Language is clear and simple</strong></p><ul><li>Short sentences</li><li>Common words</li><li>No unexplained jargon</li><li>Accessible to learners at this level</li></ul></li><li><p>[ ] <strong>Examples are practical</strong></p><ul><li>Real-world usage</li><li>Relevant to learners</li><li>Interesting and memorable</li></ul></li><li><p>[ ] <strong>Dialogue is natural</strong></p><ul><li>Sounds like actual conversation</li><li>Realistic context</li><li>Appropriate formality level</li></ul></li><li><p>[ ] <strong>Explanations are thorough but concise</strong></p><ul><li>Complete enough to understand</li><li>Not overwhelming with detail</li><li>Every concept is explained</li></ul></li></ul><h3 id="technical-validation" tabindex="-1">Technical Validation <a class="header-anchor" href="#technical-validation" aria-label="Permalink to &quot;Technical Validation&quot;">​</a></h3><ul><li><p>[ ] <strong>All links work</strong></p><ul><li>Internal links point to existing files</li><li>External links are valid</li><li>No broken references</li></ul></li><li><p>[ ] <strong>Markdown is valid</strong></p><ul><li>No syntax errors</li><li>Tables render correctly</li><li>Code blocks format properly</li><li>Headings are consistent</li></ul></li><li><p>[ ] <strong>Formatting follows style guide</strong></p><ul><li>Check <code>docs/STYLE_GUIDE.md</code></li><li>Consistent capitalization</li><li>Consistent punctuation</li><li>Consistent terminology</li></ul></li><li><p>[ ] <strong>No typos or grammatical errors</strong></p><ul><li>English is correct</li><li>Dutch text is correct (check with native speaker if needed)</li><li>Translations are accurate</li></ul></li><li><p>[ ] <strong>Images and media work</strong></p><ul><li>All image links resolve</li><li>Audio files are accessible</li><li>File paths are correct</li></ul></li><li><p>[ ] <strong>File naming is correct</strong></p><ul><li>Lesson files: <code>A0-01.md</code>, <code>A1-05.md</code>, etc.</li><li>Review files: <code>A0-R1.md</code>, <code>A1-R2.md</code>, etc.</li><li>Grammar files: lowercase with hyphens</li><li>Proper directory structure</li></ul></li></ul><h3 id="cross-curriculum-validation" tabindex="-1">Cross-Curriculum Validation <a class="header-anchor" href="#cross-curriculum-validation" aria-label="Permalink to &quot;Cross-Curriculum Validation&quot;">​</a></h3><ul><li><p>[ ] <strong>Prerequisites are accurate</strong></p><ul><li>Listed prerequisites match <code>docs/CURRICULUM.md</code></li><li>Learner can complete prerequisites before this lesson</li><li>All prerequisites are satisfied in previous content</li></ul></li><li><p>[ ] <strong>Dependencies are documented</strong></p><ul><li>Future lessons that depend on this one are listed (if known)</li><li>Prerequisites are cross-referenced correctly</li></ul></li><li><p>[ ] <strong>Vocabulary CSV is updated</strong></p><ul><li><code>shared/vocabulary/master.csv</code> includes all new words</li><li>CSV entries have all required fields</li><li>Duplicate entries are removed</li></ul></li><li><p>[ ] <strong>Grammar Map is updated</strong></p><ul><li><code>docs/GRAMMAR_MAP.md</code> includes new grammar concepts</li><li>First introduction is listed correctly</li><li>Review lessons are listed</li></ul></li><li><p>[ ] <strong>Vocabulary Roadmap is updated</strong></p><ul><li><code>docs/VOCABULARY_ROADMAP.md</code> includes new topics</li><li>Lesson placement is correct</li><li>Word counts are accurate</li></ul></li><li><p>[ ] <strong>Curriculum is updated</strong></p><ul><li><code>docs/CURRICULUM.md</code> includes this lesson</li><li>Lesson number is correct</li><li>Prerequisites are listed</li><li>Dependencies are listed</li></ul></li></ul><h3 id="review-and-assessment-validation" tabindex="-1">Review and Assessment Validation <a class="header-anchor" href="#review-and-assessment-validation" aria-label="Permalink to &quot;Review and Assessment Validation&quot;">​</a></h3><ul><li><p>[ ] <strong>Quiz has 15-20 questions</strong></p></li><li><p>[ ] <strong>Quiz covers all major concepts</strong></p></li><li><p>[ ] <strong>Quiz has answer key with explanations</strong></p></li><li><p>[ ] <strong>Active Recall section is challenging</strong></p></li><li><p>[ ] <strong>Homework is meaningful</strong></p><ul><li>Reinforces key concepts</li><li>Takes 20-30 minutes</li><li>Is engaging and relevant</li></ul></li><li><p>[ ] <strong>Summary is concise and clear</strong></p><ul><li>Recap key takeaways</li><li>List what learner now knows</li><li>Point to next lesson</li></ul></li></ul><hr><h2 id="submission-checklist" tabindex="-1">Submission Checklist <a class="header-anchor" href="#submission-checklist" aria-label="Permalink to &quot;Submission Checklist&quot;">​</a></h2><p>Before submitting a lesson:</p><ul><li>[ ] All checkboxes above are checked</li><li>[ ] No sections have red flags</li><li>[ ] File is saved in correct location</li><li>[ ] All linked files exist</li><li>[ ] Metadata header is complete</li><li>[ ] Changelog is updated (with lesson description)</li><li>[ ] You&#39;ve read through the lesson one more time</li><li>[ ] You&#39;d feel confident if a learner used this material</li></ul><hr><h2 id="common-issues-and-fixes" tabindex="-1">Common Issues and Fixes <a class="header-anchor" href="#common-issues-and-fixes" aria-label="Permalink to &quot;Common Issues and Fixes&quot;">​</a></h2><h3 id="unknown-grammar-used" tabindex="-1">&quot;Unknown grammar used&quot; <a class="header-anchor" href="#unknown-grammar-used" aria-label="Permalink to &quot;&quot;Unknown grammar used&quot;&quot;">​</a></h3><p><strong>Issue:</strong> Your reading or examples use a grammar concept not yet taught.</p><p><strong>Fix:</strong></p><ol><li>Check <code>docs/GRAMMAR_MAP.md</code></li><li>Either move the grammar concept to an earlier lesson, OR</li><li>Teach it explicitly in this lesson</li></ol><h3 id="unknown-vocabulary-used" tabindex="-1">&quot;Unknown vocabulary used&quot; <a class="header-anchor" href="#unknown-vocabulary-used" aria-label="Permalink to &quot;&quot;Unknown vocabulary used&quot;&quot;">​</a></h3><p><strong>Issue:</strong> Your examples use words not in the vocabulary list.</p><p><strong>Fix:</strong></p><ol><li>Check <code>shared/vocabulary/master.csv</code></li><li>Either add the word to this lesson&#39;s vocabulary, OR</li><li>Remove it and use a known word instead</li></ol><h3 id="too-many-new-concepts" tabindex="-1">&quot;Too many new concepts&quot; <a class="header-anchor" href="#too-many-new-concepts" aria-label="Permalink to &quot;&quot;Too many new concepts&quot;&quot;">​</a></h3><p><strong>Issue:</strong> This lesson introduces more than one major grammar concept.</p><p><strong>Fix:</strong></p><ol><li>Split into two lessons, OR</li><li>Move secondary concepts to the next lesson</li></ol><h3 id="too-much-new-vocabulary" tabindex="-1">&quot;Too much new vocabulary&quot; <a class="header-anchor" href="#too-much-new-vocabulary" aria-label="Permalink to &quot;&quot;Too much new vocabulary&quot;&quot;">​</a></h3><p><strong>Issue:</strong> More than 35 new words in one lesson.</p><p><strong>Fix:</strong></p><ol><li>Remove less essential words, OR</li><li>Spread vocabulary across multiple lessons</li></ol><h3 id="section-is-empty" tabindex="-1">&quot;Section is empty&quot; <a class="header-anchor" href="#section-is-empty" aria-label="Permalink to &quot;&quot;Section is empty&quot;&quot;">​</a></h3><p><strong>Issue:</strong> A section exists but has no meaningful content.</p><p><strong>Fix:</strong></p><ol><li>Add brief content explaining why it&#39;s not applicable, OR</li><li>Add example if one exists</li></ol><h3 id="examples-are-unclear" tabindex="-1">&quot;Examples are unclear&quot; <a class="header-anchor" href="#examples-are-unclear" aria-label="Permalink to &quot;&quot;Examples are unclear&quot;&quot;">​</a></h3><p><strong>Issue:</strong> Examples don&#39;t clearly illustrate the concept.</p><p><strong>Fix:</strong></p><ol><li>Add an explanation before the example</li><li>Simplify the example</li><li>Add multiple examples showing variation</li></ol><h3 id="dialogue-doesn-t-sound-natural" tabindex="-1">&quot;Dialogue doesn&#39;t sound natural&quot; <a class="header-anchor" href="#dialogue-doesn-t-sound-natural" aria-label="Permalink to &quot;&quot;Dialogue doesn&#39;t sound natural&quot;&quot;">​</a></h3><p><strong>Issue:</strong> The dialogue sounds artificial or robotic.</p><p><strong>Fix:</strong></p><ol><li>Remove unnecessary words</li><li>Add natural connecting phrases</li><li>Use contractions where appropriate</li><li>Ask a Dutch speaker to review</li></ol><h3 id="links-don-t-work" tabindex="-1">&quot;Links don&#39;t work&quot; <a class="header-anchor" href="#links-don-t-work" aria-label="Permalink to &quot;&quot;Links don&#39;t work&quot;&quot;">​</a></h3><p><strong>Issue:</strong> References to grammar or vocabulary files don&#39;t resolve.</p><p><strong>Fix:</strong></p><ol><li>Verify file paths are correct</li><li>Ensure files exist</li><li>Use absolute paths from project root</li><li>Update links if files are renamed</li></ol><hr><h2 id="final-sign-off" tabindex="-1">Final Sign-Off <a class="header-anchor" href="#final-sign-off" aria-label="Permalink to &quot;Final Sign-Off&quot;">​</a></h2><p>A lesson is ready for submission when:</p><p>✅ All 20 sections present and complete ✅ No unknown grammar introduced ✅ No unknown vocabulary introduced ✅ All links work ✅ Markdown is valid ✅ Style guide is followed ✅ Curriculum/Grammar Map/Vocabulary Roadmap updated ✅ Vocabulary CSV updated ✅ No typos or errors ✅ You&#39;d feel confident teaching this material</p><p>If any of these are not true, revise before submitting.</p>',70)])])}const m=e(t,[["render",s]]);export{h as __pageData,m as default};
